  if(!(Test-Path $dir)){New-Item -ItemType Directory -Path $dir -Force|Out-Null}
  $doc=@"
<!doctype html><html lang="en" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>$title | Baloch Sahab Automation</title><meta name="description" content="$desc"><link rel="canonical" href="https://balochsahab.com$canon"><meta property="og:type" content="website"><meta property="og:title" content="$title | Baloch Sahab Automation"><meta property="og:description" content="$desc"><meta property="og:url" content="https://balochsahab.com$canon"><meta property="og:image" content="https://balochsahab.com/assets/img/og-cover.svg"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="$title | Baloch Sahab Automation"><meta name="twitter:description" content="$desc"><meta name="twitter:image" content="https://balochsahab.com/assets/img/og-cover.svg"><link rel="icon" href="/assets/img/favicon.svg" type="image/svg+xml"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&amp;family=Sora:wght@500;600;700&amp;display=swap" rel="stylesheet"><link rel="stylesheet" href="/assets/css/main.css"><script src="/assets/js/main.js" defer></script></head><body><a class="skip-link" href="#main-content">Skip to content</a><header class="site-header"><div class="container nav-wrap"><a class="brand" href="/" aria-label="Baloch Sahab Automation home"><span class="brand-mark">BS</span><span>Baloch Sahab Automation</span></a><nav class="desktop-nav" aria-label="Primary navigation"><a href="/services.html">Services</a><a href="/solutions.html">Solutions</a><a href="/features.html">Features</a><a href="/pricing.html">Pricing</a><a href="/about.html">About</a><a href="/blog/">Blog</a><a href="/docs/">Docs</a></nav><div class="nav-actions"><button type="button" data-theme-toggle aria-label="Toggle color theme">Theme</button><a class="btn btn-primary" href="/contact.html">Get Started</a><button type="button" data-nav-toggle aria-label="Open navigation" aria-expanded="false">Menu</button></div></div><nav class="mobile-nav" data-mobile-nav aria-label="Mobile navigation"><a href="/services.html">Services</a><a href="/solutions.html">Solutions</a><a href="/features.html">Features</a><a href="/pricing.html">Pricing</a><a href="/about.html">About</a><a href="/blog/">Blog</a><a href="/docs/">Docs</a><a href="/faq.html">FAQ</a><a href="/contact.html">Contact</a></nav></header><main id="main-content">$body</main><footer class="site-footer"><div class="container footer-grid"><div><a class="brand" href="/"><span class="brand-mark">BS</span><span>Baloch Sahab Automation</span></a><p>AI-powered automation that helps creators and businesses publish, scale, and grow.</p><div class="social-links"><a href="https://www.tiktok.com" aria-label="TikTok">TikTok</a><a href="https://www.youtube.com" aria-label="YouTube">YouTube</a><a href="https://www.instagram.com" aria-label="Instagram">Instagram</a></div></div><div><h3>Product</h3><a href="/features.html">Features</a><a href="/services.html">Services</a><a href="/pricing.html">Pricing</a><a href="/app/">Customer Portal</a></div><div><h3>Company</h3><a href="/about.html">About</a><a href="/solutions.html">Solutions</a><a href="/blog/">Blog</a><a href="/contact.html">Contact</a></div><div><h3>Legal</h3><a href="/privacy-policy.html">Privacy</a><a href="/terms-of-service.html">Terms</a><a href="/cookie-policy.html">Cookies</a><a href="/faq.html">FAQ</a></div></div><div class="container footer-bottom"><p>&copy; <span data-year>2026</span> Baloch Sahab Automation. All Rights Reserved.</p><a href="mailto:shamsfida92@gmail.com">shamsfida92@gmail.com</a></div></footer></body></html>
"@
