function Hero($eyebrow,$heading,$text){"<section class=`"page-hero`"><div class=`"container`"><p class=`"eyebrow`">$eyebrow</p><h1>$heading</h1><p>$text</p></div></section>"}
function Cards($items,$class='feature-card',$grid='grid-3'){$cards=($items|ForEach-Object{"<article class=`"$class reveal`"><h2>$($_[0])</h2><p>$($_[1])</p></article>"})-join'';"<section class=`"section`"><div class=`"container $grid`">$cards</div></section>"}
function Faq($items){$rows=($items|ForEach-Object{"<div class=`"faq-item`"><button type=`"button`" data-faq-trigger aria-expanded=`"false`">$($_[0])</button><div class=`"faq-panel`"><p>$($_[1])</p></div></div>"})-join'';"<section class=`"section`"><div class=`"container faq-list`">$rows</div></section>"}

